<?php

namespace App\Modules\Knowledge\Actions;

use App\Modules\Knowledge\Data\FieldDefinitionData;
use App\Modules\Knowledge\Enums\FieldType;

/**
 * The Markdown page `docs/architecture/fields.md`, generated from the field files so it never drifts.
 */
final class RenderFieldTable
{
    /**
     * @param  list<FieldDefinitionData>  $definitions
     */
    public function handle(array $definitions): string
    {
        $lines = [
            '# Field definitions',
            '',
            '<!-- Generated by `php artisan atlas:fields:generate` from `data/fields/*.yaml`. Do not edit. -->',
            '',
            'Every field value has a status (`ai_draft` → `sourced` → `community_supported` → `verified`, or',
            '`disputed`). "unknown" is always a valid answer. Changing a field\'s type, options or anchors once it',
            'has values needs a new version (`atlas:fields:sync` refuses the change).',
        ];

        foreach ($this->byWave($definitions) as $wave => $fields) {
            array_push($lines, '', "## Wave {$wave}", '', '| Field | Version | Group | Type | Values | Flags |', '|---|---|---|---|---|---|');

            foreach ($fields as $field) {
                $lines[] = sprintf(
                    '| `%s`<br>%s · %s | %d | %s | %s | %s | %s |',
                    $field->key,
                    $this->cell($field->label['en']),
                    $this->cell($field->label['bn']),
                    $field->version,
                    $field->group,
                    $field->type->value,
                    $this->values($field),
                    $this->flags($field),
                );
            }

            foreach ($fields as $field) {
                if ($field->type !== FieldType::Scale1To5 || $field->anchors === null) {
                    continue;
                }

                array_push($lines, '', "### `{$field->key}` anchors", '', '| | English | বাংলা |', '|---|---|---|');

                foreach ($field->anchors['en'] as $point => $text) {
                    $lines[] = sprintf('| %d | %s | %s |', $point, $this->cell($text), $this->cell($field->anchors['bn'][$point]));
                }
            }
        }

        return implode("\n", $lines)."\n";
    }

    /**
     * @param  list<FieldDefinitionData>  $definitions
     * @return array<int, list<FieldDefinitionData>>
     */
    private function byWave(array $definitions): array
    {
        $waves = [];

        foreach ($definitions as $definition) {
            $waves[$definition->wave][] = $definition;
        }

        ksort($waves);

        return $waves;
    }

    private function values(FieldDefinitionData $field): string
    {
        return match ($field->type) {
            FieldType::Scale1To5 => '1–5, anchors below',
            FieldType::Boolean => 'yes · no',
            FieldType::Text => 'text (bn, en)',
            default => implode(' · ', array_map(
                fn (string $option): string => "`{$option}` {$this->cell($field->optionLabels[$option]['en'] ?? '')}",
                $field->options ?? [],
            )),
        };
    }

    private function flags(FieldDefinitionData $field): string
    {
        $flags = array_keys(array_filter(['sensitive' => $field->sensitive, 'requires source' => $field->requiresSource]));

        return $flags === [] ? '—' : implode(', ', $flags);
    }

    private function cell(string $text): string
    {
        return str_replace(['|', "\n"], ['\\|', ' '], $text);
    }
}
